PRAGMA foreign_keys=ON;
CREATE TABLE companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT DEFAULT 'delivery',abn TEXT,contact_name TEXT,email TEXT,phone TEXT,address TEXT,car_rate REAL DEFAULT 0,van_rate REAL DEFAULT 0,other_rate REAL DEFAULT 0,rate_type TEXT DEFAULT 'fixed',active INTEGER DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','manager','staff','driver','labour')),company_id TEXT REFERENCES companies(id),driver_id TEXT,labour_id TEXT,active INTEGER DEFAULT 1,must_reset_password INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE sessions(id_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE drivers(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),name TEXT NOT NULL,mobile TEXT,email TEXT,vehicle TEXT,active INTEGER DEFAULT 1,legacy_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE labour(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),name TEXT NOT NULL,mobile TEXT,email TEXT,category TEXT,active INTEGER DEFAULT 1,legacy_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE delivery_days(id TEXT PRIMARY KEY,work_date TEXT UNIQUE NOT NULL,company_id TEXT REFERENCES companies(id),status TEXT DEFAULT 'open',notes TEXT,created_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE delivery_records(id TEXT PRIMARY KEY,day_id TEXT NOT NULL REFERENCES delivery_days(id),driver_id TEXT REFERENCES drivers(id),driver_name TEXT NOT NULL,block_name TEXT,vehicle TEXT,parcels INTEGER DEFAULT 0,delivered INTEGER DEFAULT 0,failed INTEGER DEFAULT 0,base_rate REAL DEFAULT 0,bonus REAL DEFAULT 0,adjustment REAL DEFAULT 0,total_pay REAL DEFAULT 0,payment_ref TEXT,payment_status TEXT DEFAULT 'Pending',notes TEXT,legacy_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE driver_submissions(id TEXT PRIMARY KEY,driver_id TEXT REFERENCES drivers(id),company_id TEXT REFERENCES companies(id),work_date TEXT NOT NULL,start_time TEXT,finish_time TEXT,delivered INTEGER DEFAULT 0,failed INTEGER DEFAULT 0,failure_reasons TEXT,evidence_key TEXT,status TEXT DEFAULT 'pending',reviewed_by TEXT REFERENCES users(id),reviewed_at TEXT,review_note TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE labour_shifts(id TEXT PRIMARY KEY,labour_id TEXT REFERENCES labour(id),company_id TEXT REFERENCES companies(id),work_date TEXT NOT NULL,start_time TEXT,finish_time TEXT,break_minutes INTEGER DEFAULT 0,hours REAL DEFAULT 0,pay_rate REAL DEFAULT 0,bill_rate REAL DEFAULT 0,pay_total REAL DEFAULT 0,bill_total REAL DEFAULT 0,status TEXT DEFAULT 'pending',approved_by TEXT REFERENCES users(id),legacy_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE rate_cards(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),category TEXT NOT NULL,effective_date TEXT NOT NULL,end_date TEXT,ordinary_rate REAL DEFAULT 0,overtime_rate REAL DEFAULT 0,night_rate REAL DEFAULT 0,holiday_rate REAL DEFAULT 0,legacy_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE invoices(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),invoice_number TEXT UNIQUE NOT NULL,invoice_date TEXT NOT NULL,due_date TEXT,subtotal REAL DEFAULT 0,tax REAL DEFAULT 0,total REAL DEFAULT 0,status TEXT DEFAULT 'draft',notes TEXT,legacy_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE delivery_blocks(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),name TEXT NOT NULL,description TEXT,active INTEGER DEFAULT 1,legacy_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE driver_assignments(id TEXT PRIMARY KEY,driver_id TEXT REFERENCES drivers(id),block_id TEXT REFERENCES delivery_blocks(id),work_date TEXT NOT NULL,company_id TEXT REFERENCES companies(id),legacy_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE audit_log(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details TEXT,created_at TEXT NOT NULL);
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX delivery_records_day_idx ON delivery_records(day_id);
CREATE INDEX submissions_driver_idx ON driver_submissions(driver_id,work_date);
CREATE INDEX shifts_labour_idx ON labour_shifts(labour_id,work_date);
